        if c['kind'] == 'defect':
            defects.append({'n': c['n'], 'rows': c['rows']})
    d['defects'] = defects
    out = collections.OrderedDict()
    for kind in ('history', 'plan', 'detail', 'tests'):
        ns = [c['n'] for c in cl if c['kind'] == kind]
        if ns: out[kind] = ns
    d['move_out'] = out
    nprop = sum(1 for c in cl if c['kind'] in ('property', 'choice'))
    ndef = len(defects)
    chk = [x for x in v['checks_found'] if x != "a ledger row's status disagrees"]
    if v['shape_kind'] == 'not about the tree':
        t = 'not about the tree'
    elif k in DJ.MERGE:
        t = 'merged'
        d['into'], d['why'] = DJ.MERGE[k]
    elif nprop == 0 and ndef > 0:
        t = 'defect'
    elif parts:
        t = 'split'
    elif out.get('history') or out.get('plan') or out.get('detail') or len(out.get('tests', [])) > 1 or chk or cut:
        t = 'rewritten'
    else:
        t = 'stays'
    d['type'] = t
    v['disp'] = d

# ---- groups
