used = set()
for gid, name, shared, bl, extra in GJ.G:
    ents = set(extra)
    for b in bl:
        ents |= set(ovl[b]['entries']); used.add(b)
    ents = sorted(ents)
    groups.append({'id': gid, 'name': name, 'shared': shared, 'sources': bl, 'entries': ['F-%d' % x for x in ents]})
unused = [b for b in ovl if b not in used]
